function drawFaceDiagram(canvas,points=[]){
 canvas.width=640;canvas.height=760;const c=canvas.getContext('2d');c.fillStyle='#faf8f3';c.fillRect(0,0,640,760);c.strokeStyle='#aa9270';c.lineWidth=2.5;c.lineCap='round';
 const path=(fn)=>{c.beginPath();fn();c.stroke();};
 c.fillStyle='#f2e9db';c.beginPath();c.moveTo(320,88);c.bezierCurveTo(155,88,135,225,159,375);c.bezierCurveTo(166,483,237,565,320,591);c.bezierCurveTo(403,565,474,483,481,375);c.bezierCurveTo(505,225,485,88,320,88);c.fill();c.stroke();
 path(()=>{c.moveTo(160,302);c.bezierCurveTo(113,266,125,398,169,405);c.moveTo(480,302);c.bezierCurveTo(527,266,515,398,471,405);c.moveTo(246,555);c.lineTo(238,645);c.lineTo(128,697);c.moveTo(394,555);c.lineTo(402,645);c.lineTo(512,697);});
 path(()=>{c.moveTo(195,274);c.quadraticCurveTo(236,254,275,274);c.moveTo(365,274);c.quadraticCurveTo(404,254,445,274);c.moveTo(195,310);c.quadraticCurveTo(235,281,275,310);c.quadraticCurveTo(235,337,195,310);c.moveTo(365,310);c.quadraticCurveTo(405,281,445,310);c.quadraticCurveTo(405,337,365,310);});
 for(const x of [237,403]){c.beginPath();c.arc(x,309,9,0,Math.PI*2);c.fillStyle='#9b896d';c.fill();}
 path(()=>{c.moveTo(313,326);c.lineTo(293,407);c.quadraticCurveTo(320,428,347,407);c.moveTo(265,474);c.quadraticCurveTo(294,452,320,465);c.quadraticCurveTo(346,452,375,474);c.quadraticCurveTo(320,514,265,474);c.moveTo(265,474);c.quadraticCurveTo(320,482,375,474);});
 c.fillStyle='#74674f';c.textAlign='center';c.font='16px sans-serif';c.fillText('แผนผังใบหน้ากลาง · ไม่ใช่ภาพคนไข้',320,38);
 points.forEach((p,i)=>{c.beginPath();c.arc(p.x,p.y,13,0,Math.PI*2);c.fillStyle='#94713c';c.fill();c.fillStyle='#fff';c.font='bold 14px sans-serif';c.fillText(String(i+1),p.x,p.y+5);});
}
function mountFaceEditor(){
 const host=document.createElement('details');host.className='field full face-editor';host.innerHTML=`<summary><span><strong>ภาพใบหน้าและแผนการปรึกษา</strong><small>Face Detail / Face Simulation · ไม่บังคับ</small></span><span class="face-chevron" aria-hidden="true">⌄</span></summary><div class="face-body"><p class="face-intro">เพิ่มภาพเพื่อระบุตำแหน่งและบันทึกรายละเอียดประกอบการปรึกษา</p><label class="field" for="face-source">แหล่งภาพ<select id="face-source"><option value="photo">รูปจริงของผู้รับบริการ</option><option value="diagram">แผนผังใบหน้าจำลอง · ไม่ถ่ายรูป</option></select></label><p id="face-source-note" class="face-intro">รูปจริงต้องมีความยินยอมสำหรับการเก็บภาพก่อน–หลัง</p><label id="face-upload-area" class="face-upload" for="face-file"><strong>1. เลือกภาพใบหน้า</strong><span>JPG หรือ PNG ขนาดไม่เกิน 10 MB</span><input id="face-file" type="file" accept="image/jpeg,image/png"></label><div class="face-controls"><label class="field" for="face-mode">2. เลือกเครื่องมือ<select id="face-mode"><option value="detail">ระบุตำแหน่งบนใบหน้า</option><option value="simulate">จำลองการปรับรูปทรง</option></select></label><div id="face-simulation-controls" class="face-sliders" hidden><label class="field" for="face-radius">ขนาดบริเวณที่ปรับ<input id="face-radius" type="range" min="20" max="160" value="70"></label><label class="field" for="face-strength">ระดับการปรับ · หด − / ขยาย +<input id="face-strength" type="range" min="-60" max="60" value="0"></label><p class="face-intro">ภาพจำลองใช้ประกอบการปรึกษา ไม่ใช่การคาดการณ์ผลการรักษา</p></div></div><div class="face-preview"><p id="face-status" role="status">ยังไม่ได้เลือกภาพ</p><canvas id="face-canvas" width="640" height="480" style="display:none;width:100%;height:auto;touch-action:none;border-radius:12px"></canvas></div><div class="face-actions"><button type="button" id="face-reset">คืนภาพต้นฉบับ / ล้างจุด</button><button type="button" id="face-remove">ลบภาพ</button></div><label class="field face-notes" for="face-notes">3. รายละเอียดตำแหน่ง / แผนการปรึกษา<textarea id="face-notes" rows="4" maxlength="10000" placeholder="เช่น จุด 1: รายละเอียดบริเวณที่ปรึกษา"></textarea></label></div>`;
 $('#modal-form .formgrid').append(host);
 $('#face-mode').onchange=()=>{$('#face-simulation-controls').hidden=$('#face-mode').value!=='simulate';};
 const canvas=$('#face-canvas'),ctx=canvas.getContext('2d');let original=null,points=[],center=null,current=null,version=0,sourceKind='photo',drafts={};
 $('#face-source').onchange=()=>{
 drafts[sourceKind]={original,points,center,current,width:canvas.width,height:canvas.height,notes:$('#face-notes').value,radius:$('#face-radius').value,strength:$('#face-strength').value,mode:$('#face-mode').value};version++;
 sourceKind=$('#face-source').value;const saved=drafts[sourceKind];
 if(saved){canvas.width=saved.width;canvas.height=saved.height;({original,points,center,current}=saved);$('#face-notes').value=saved.notes;$('#face-radius').value=saved.radius;$('#face-strength').value=saved.strength;$('#face-mode').value=saved.mode;}
 else{points=[];center=null;current=null;original=null;$('#face-notes').value='';$('#face-strength').value='0';$('#face-mode').value='detail';if(sourceKind==='diagram'){drawFaceDiagram(canvas);original=ctx.getImageData(0,0,640,760);}}
 $('#face-upload-area').hidden=sourceKind==='diagram';$('#face-mode').disabled=sourceKind==='diagram';$('#face-simulation-controls').hidden=sourceKind==='diagram'||$('#face-mode').value!=='simulate';
 $('#face-source-note').textContent=sourceKind==='diagram'?'แผนผังกลางสำหรับบันทึกตำแหน่ง ไม่ใช่ภาพ before–after หรือผลการรักษาจริง บันทึกเฉพาะจุดและข้อความ ไม่ส่งรูปจริง':'รูปจริงต้องมีความยินยอมสำหรับการเก็บภาพก่อน–หลัง';
 canvas.style.display=original?'block':'none';$('#face-status').textContent=original?'คลิกภาพเพื่อระบุตำแหน่ง':'ยังไม่ได้เลือกภาพ';draw();
 };
 function draw(){if(!original)return;current=new ImageData(new Uint8ClampedArray(original.data),original.width,original.height);if(center){const radius=Number($('#face-radius').value),strength=Number($('#face-strength').value)/100;for(let y=Math.max(0,Math.floor(center.y-radius));y<Math.min(canvas.height,center.y+radius);y++){for(let x=Math.max(0,Math.floor(center.x-radius));x<Math.min(canvas.width,center.x+radius);x++){const dx=x-center.x,dy=y-center.y,dist=Math.hypot(dx,dy);if(dist>=radius)continue;const scale=1-strength*Math.pow(1-dist/radius,2),sx=Math.max(0,Math.min(canvas.width-1,Math.round(center.x+dx*scale))),sy=Math.max(0,Math.min(canvas.height-1,Math.round(center.y+dy*scale)));const dst=(y*canvas.width+x)*4,src=(sy*canvas.width+sx)*4;for(let k=0;k<4;k++)current.data[dst+k]=original.data[src+k];}}}ctx.putImageData(current,0,0);points.forEach((p,i)=>{ctx.fillStyle='#9c752b';ctx.beginPath();ctx.arc(p.x,p.y,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.textAlign='center';ctx.font='bold 13px sans-serif';ctx.fillText(String(i+1),p.x,p.y+4);});}
 function clear(){drafts={};sourceKind='photo';$('#face-source').value='photo';$('#face-upload-area').hidden=false;$('#face-mode').disabled=false;$('#face-mode').value='detail';$('#face-simulation-controls').hidden=true;$('#face-source-note').textContent='รูปจริงต้องมีความยินยอมสำหรับการเก็บภาพก่อน–หลัง';version++;original=null;points=[];center=null;current=null;canvas.style.display='none';$('#face-file').value='';$('#face-notes').value='';$('#face-strength').value='0';$('#face-status').textContent='ยังไม่ได้เลือกภาพ';}
 $('#face-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const request=++version;if(!['image/jpeg','image/png'].includes(file.type)||file.size>10*1024*1024){toast('เลือก JPG / PNG ไม่เกิน 10 MB');e.target.value='';return;}try{const img=await createImageBitmap(file);if(request!==version||!host.isConnected){img.close();return;}const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);ctx.drawImage(img,0,0,canvas.width,canvas.height);img.close();original=ctx.getImageData(0,0,canvas.width,canvas.height);points=[];center=null;$('#face-notes').value='';$('#face-strength').value='0';canvas.style.display='block';$('#face-status').textContent='คลิกภาพเพื่อระบุตำแหน่ง';draw();}catch{toast('ไม่สามารถอ่านภาพนี้ได้');}};
 canvas.onclick=e=>{if(!original)return;const rect=canvas.getBoundingClientRect(),p={x:(e.clientX-rect.left)*canvas.width/rect.width,y:(e.clientY-rect.top)*canvas.height/rect.height};if($('#face-mode').value==='detail'){if(points.length>=30)return toast('ระบุได้ไม่เกิน 30 จุด');points.push(p);$('#face-notes').value+=(points.length>1?'\n':'')+'จุด '+points.length+': ';$('#face-status').textContent='ระบุแล้ว '+points.length+' จุด';}else{center=p;$('#face-status').textContent='เลือกบริเวณแล้ว เลื่อนระดับการปรับเพื่อจำลองภาพ';}draw();};
 $('#face-radius').oninput=draw;$('#face-strength').oninput=draw;$('#face-reset').onclick=()=>{points=[];center=null;$('#face-strength').value='0';$('#face-notes').value='';draw();};$('#face-remove').onclick=clear;
 return {clear,data(){if(!original)return null;if(sourceKind==='diagram')return {kind:'diagram',points,notes:$('#face-notes').value};const source=document.createElement('canvas');source.width=canvas.width;source.height=canvas.height;source.getContext('2d').putImageData(original,0,0);return {original:source.toDataURL('image/jpeg',.85),simulation:canvas.toDataURL('image/jpeg',.85),notes:$('#face-notes').value};}};
}
async function showFaceDetail(id){const face=await api('procedures/face?id='+id);if(face.kind==='diagram'){modal('แผนผังใบหน้า / ประวัติตำแหน่ง',`<p class="notice">แผนผังกลาง ไม่ใช่ภาพคนไข้หรือภาพผลการรักษาก่อน–หลัง</p><canvas id="saved-face-diagram" style="width:100%;height:auto"></canvas><p style="white-space:pre-wrap">${esc(face.notes)}</p>`);drawFaceDiagram($('#saved-face-diagram'),face.points);return;}if(!face.original)return toast('ไม่มีภาพ Face Detail ในรายการนี้');modal('Face Detail / Face Simulation',`<p class="notice">ภาพจำลองเพื่อประกอบการปรึกษา ไม่ใช่การคาดการณ์ผลการรักษา</p><div class="formgrid"><div><h3>ภาพต้นฉบับ</h3><img src="${esc(face.original)}" alt="ภาพใบหน้าต้นฉบับ" style="width:100%"></div><div><h3>ตำแหน่ง / ภาพจำลอง</h3><img src="${esc(face.simulation)}" alt="ตำแหน่งบนใบหน้าและภาพจำลอง" style="width:100%"></div></div><p style="white-space:pre-wrap">${esc(face.notes)}</p>`);}

boot();
